/**
 * Jinx Alchemist + Wraith: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Wraith
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { hasAbilityOf } from '#lib/core/rules/gained-abilities.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { jinxGuessers } from '#lib/core/rules/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { alchemistAs, bagNotes } from './alchemist.test-support.ts';

describe('Alchemist + Wraith jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'wraith');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('wraith')?.name).toBe('Wraith');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'wraith'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['wraith'])).not.toContain(jinx);
	});

	it("is data in the Alchemist's rules", () => {
		// Wiki: "An Alchemist-Wraith has no Wraith ability & a Wraith is in play. After each execution, a living Alchemist-Wraith may publicly guess a living player as the Wraith. If correct, the Demon must choose the Wraith tonight."
		expect(jinxRulesBetween('alchemist', 'wraith')).toEqual({
			withPartnerAbility: 'partner-in-play',
			guessesPartner: true
		});
	});

	// Seat 0 the Alchemist-Wraith, seat 2 the real Wraith.
	const base = alchemistAs('wraith', ['chef', 'wraith', 'imp', 'empath']);
	const guesses = (s: typeof base) => jinxGuessers(s.game, s.characters);
	const alerts = (s: typeof base) =>
		nightStepAlerts(s.game, 'imp', s.characters).filter((a) => a.kind === 'guessed');

	describe('an Alchemist-Wraith has no Wraith ability, and a Wraith is in play', () => {
		it('notes the real Wraith at setup when the Alchemist is chosen', () => {
			// Wiki: "a Wraith is in play"
			const note =
				'Alchemist with the Wraith ability: the Wraith is in play too, and the Alchemist has no ability.';
			expect(bagNotes('wraith')).toContain(note);
			expect(bagNotes('wraith', false)).not.toContain(note);
		});

		it('leaves the Alchemist-Wraith with no ability, and the real Wraith with theirs', () => {
			// Wiki: "An Alchemist-Wraith has no Wraith ability"
			const state = abilityState(base.game, base.seat(0), base.characters);
			expect(state.works).toBe(false);
			expect(state.impairments).toMatchObject([
				{ reason: 'no-ability', source: { characterId: 'wraith' } }
			]);
			expect(hasAbilityOf(base.game, base.seat(0), 'wraith', base.characters)).toBe(false);
			expect(hasAbilityOf(base.game, base.seat(2), 'wraith', base.characters)).toBe(true);
		});
	});

	describe('after each execution, a living Alchemist-Wraith may guess the Wraith', () => {
		it('lets them guess once someone has been executed today', () => {
			// Wiki: "After each execution, a living Alchemist-Wraith may publicly guess a living player as the Wraith."
			expect(guesses(base)).toEqual([]);
			const s = base.execute('chef');
			expect(guesses(s)).toEqual([
				{ seatId: s.seat(0), owner: 'alchemist', partner: 'wraith', partnerSeats: [s.seat(2)] }
			]);
		});

		it('says at the Demon step that a right guess makes the Demon choose the Wraith', () => {
			// Wiki: "If correct, the Demon must choose the Wraith tonight."
			const s = base.execute('chef');
			expect(alerts(s)).toMatchObject([
				{ kind: 'guessed', seatId: s.seat(0), partner: 'wraith', works: true }
			]);
			expect(alerts(base)).toEqual([]);
		});

		it('gives a dead Alchemist-Wraith no guess, nor one with no living Wraith', () => {
			// Wiki: "a living Alchemist-Wraith may publicly guess a living player as the Wraith"
			expect(guesses(base.dies(0).execute('chef'))).toEqual([]);
			expect(guesses(base.dies(2).execute('chef'))).toEqual([]);
		});
	});
});
